-#define xw32(reg, val)	iowrite32(val, ioaddr + (reg))
-#define xr32(reg)	ioread32(ioaddr + (reg))
-#define xr8(reg)	ioread8(ioaddr + (reg))
-
-/* IO registers on the card, offsets */
-#define CSR0	0x00
-#define CSR1	0x08
-#define CSR2	0x10
-#define CSR3	0x18
-#define CSR4	0x20
-#define CSR5	0x28
-#define CSR6	0x30
-#define CSR7	0x38
-#define CSR8	0x40
-#define CSR9	0x48
-#define CSR10	0x50
-#define CSR11	0x58
-#define CSR12	0x60
-#define CSR13	0x68
-#define CSR14	0x70
-#define CSR15	0x78
-#define CSR16	0x80
-
-/* PCI registers */
-#define PCI_POWERMGMT 	0x40
-
-/* Offsets of the buffers within the descriptor pages, in bytes */
-
-#define NUMDESCRIPTORS 4
-
-static int bufferoffsets[NUMDESCRIPTORS] = {128,2048,4096,6144};
-
-
-struct xircom_private {
-	/* Send and receive buffers, kernel-addressable and dma addressable forms */
-
-	__le32 *rx_buffer;
-	__le32 *tx_buffer;
-
-	dma_addr_t rx_dma_handle;
-	dma_addr_t tx_dma_handle;
-
-	struct sk_buff *tx_skb[4];
-
-	void __iomem *ioaddr;
-	int open;
-
-	/* transmit_used is the rotating counter that indicates which transmit
-	   descriptor has to be used next */
-	int transmit_used;
-
-	/* Spinlock to serialize register operations.
-	   It must be helt while manipulating the following registers:
-	   CSR0, CSR6, CSR7, CSR9, CSR10, CSR15
-	 */
-	spinlock_t lock;
-
-	struct pci_dev *pdev;
-	struct net_device *dev;
-};
