-#if defined DEBUG && DEBUG > 1
-static void print_binary(unsigned int number)
-{
-	int i,i2;
-	char buffer[64];
-	memset(buffer,0,64);
-	i2=0;
-	for (i=31;i>=0;i--) {
-		if (number & (1<<i))
-			buffer[i2++]='1';
-		else
-			buffer[i2++]='0';
-		if ((i&3)==0)
-			buffer[i2++]=' ';
-	}
-	pr_debug("%s\n",buffer);
-}
-#endif
