+	KUNIT_EXPECT_NULL_MSG(test, strstr(buf, "+0x"),
+			      "Unexpected offset in no_offset: %s", buf);
+	/* sprint_symbol_no_offset is a sprint_symbol() variant; lineinfo is
+	 * intentionally only appended in sprint_backtrace*() context.
